import { motion, useReducedMotion } from 'framer-motion';
import { ArrowUp } from 'lucide-react';
import { useInView } from '@/hooks/useInView';

/** Signal-strength bars, ascending like a reception readout. */
const HEIGHTS = [10, 16, 22, 28, 34];
const CYCLE = 1.4;

/**
 * 信号上行 — five bars light up one by one from weak to strong (zinc-950),
 * then the whole column goes dark and the cycle repeats every 1.4s; a small
 * arrow above keeps sliding up and fading out.
 */
export default function Uplink() {
  const reduced = useReducedMotion();
  const { ref, inView } = useInView<HTMLDivElement>();
  const running = inView && !reduced;

  return (
    <div ref={ref} className="flex h-full w-full flex-col items-center justify-center gap-5">
      <div className="flex flex-col items-center gap-2">
        {/* arrow drifting up on each cycle */}
        <motion.span
          className="flex text-zinc-950"
          animate={running ? { y: [4, -7], opacity: [0, 1, 0] } : { y: 0, opacity: 0.4 }}
          transition={
            running
              ? { duration: CYCLE, repeat: Infinity, times: [0, 0.55, 1], ease: 'easeOut' }
              : { duration: 0.2 }
          }
        >
          <ArrowUp className="h-3.5 w-3.5" strokeWidth={2.5} />
        </motion.span>

        <div className="flex h-9 items-end gap-1.5">
          {HEIGHTS.map((h, i) => (
            <motion.span
              key={i}
              className="block w-1.5 rounded-full"
              style={{ height: h }}
              animate={
                running
                  ? { backgroundColor: ['#e4e4e7', '#09090b', '#09090b', '#e4e4e7'] }
                  : { backgroundColor: '#e4e4e7' }
              }
              transition={
                running
                  ? {
                      duration: CYCLE,
                      repeat: Infinity,
                      delay: i * 0.11,
                      times: [0, 0.18, 0.78, 1],
                      ease: 'easeInOut',
                    }
                  : { duration: 0.2 }
              }
            />
          ))}
        </div>
      </div>
      <span className="font-mono text-[11px] uppercase tracking-[0.08em] text-zinc-400">
        uplink
      </span>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';

/**
 * IntersectionObserver hook with enter/exit hysteresis, used to gate live previews.
 *
 * Why hysteresis: a single observer with a small rootMargin causes boundary thrash —
 * cards just inside the margin mount, then unmount the moment they scroll a few px
 * past the viewport edge, producing visible white flashes ("闪屏") while scrolling.
 *
 * - enter observer: mounts the preview 240px BEFORE it reaches the viewport,
 *   so content is already there when the user sees it.
 * - exit observer: keeps the preview mounted until it is 600px PAST the viewport,
 *   so briefly scrolling by never blanks a card.
 */
export function useInView<T extends HTMLElement>(enterMargin = '240px', exitMargin = '600px') {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(() => typeof IntersectionObserver === 'undefined');

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') return;

    const enter = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) setInView(true);
      },
      { rootMargin: enterMargin, threshold: 0 },
    );
    const exit = new IntersectionObserver(
      (entries) => {
        if (entries[0] && !entries[0].isIntersecting) setInView(false);
      },
      { rootMargin: exitMargin, threshold: 0 },
    );

    enter.observe(el);
    exit.observe(el);
    return () => {
      enter.disconnect();
      exit.disconnect();
    };
  }, [enterMargin, exitMargin]);

  return { ref, inView };
}

